(function(){
 'use strict';
 const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const round=n=>Math.round(n*10)/10;
 function context(r){const clash=r.interpretation.timeline.years[0].relations.find(f=>f.kind==='충'&&f.members.some(p=>p.label==='일주'));return {dayPillar:r.pillars[2].gan+r.pillars[2].zhi,strength:r.interpretation.strength.label,structure:r.interpretation.structure.candidate,year:r.year,clashPosition:clash?clash.label:'일지와 세운의 충'};}
 function interpolate(text,r){const ctx=context(r);return text.replace(/\{\{(\w+)\}\}/g,(m,k)=>escape(ctx[k]===undefined?'':ctx[k]));}
 function select(r,category){const c=window.OngyeolContent,tags=new Set(r.interpretation.tags.map(v=>v.id));return [c.base[category],...c.rules.filter(rule=>rule.category===category&&rule.all.every(t=>tags.has(t))).slice(0,3)];}
 function category(r,name='love'){return select(r,name).map(v=>'<article class="interpretation-scene"><h4>'+interpolate(v.title,r)+'</h4><div><span>잘 쓰면</span><p>'+interpolate(v.good,r)+'</p></div><div class="honest-line"><span>놓치기 쉬운 점</span><p>'+interpolate(v.caution,r)+'</p></div></article>').join('')+'<details class="insight-evidence"><summary>이번 설명에 연결된 특징 태그</summary><p>'+r.interpretation.tags.map(v=>'<strong>'+escape(v.id.replace(/_/g,' '))+'</strong>: '+escape(v.evidence)).join('<br>')+'</p><p>오락·자기 성찰용 참고 해석입니다. 재물 항목은 투자·수익 예측이나 개인 금융 조언을 제공하지 않습니다.</p></details>';}
 function character(r){const key=r.interpretation.strength.label.split(' ')[0],group=key==='신강'?'strong':key==='신약'?'weak':'middle';return window.OngyeolContent.characters[r.day][group];}
 function radar(r){
  const elements=window.OngyeolInterpretationRules.elements,values=r.interpretation.weighted.percent,cx=150,cy=145,radius=102;
  const point=(i,size)=>[cx+Math.cos(-Math.PI/2+i*2*Math.PI/5)*size,cy+Math.sin(-Math.PI/2+i*2*Math.PI/5)*size];
  const polygon=size=>elements.map((e,i)=>point(i,size).join(',')).join(' ');
  const data=elements.map((e,i)=>point(i,radius*Math.min(1,values[e]/50)).join(',')).join(' ');
  return '<svg class="weighted-radar" viewBox="0 0 300 285" role="img" aria-label="지장간과 월지 가중 오행. '+elements.map(e=>e+' '+round(values[e])+'%').join(', ')+'"><g fill="none" stroke="#d6dcce">'+[.25,.5,.75,1].map(n=>'<polygon points="'+polygon(radius*n)+'"/>').join('')+elements.map((e,i)=>'<path d="M'+cx+' '+cy+'L'+point(i,radius).join(' ')+'"/>').join('')+'</g><polygon points="'+data+'" fill="#a5b88766" stroke="#617e53" stroke-width="2"/>'+elements.map((e,i)=>{const [x,y]=point(i,radius+20);return '<text x="'+x+'" y="'+y+'" text-anchor="middle" dominant-baseline="middle" font-size="14" fill="#193c34">'+e+'</text>';}).join('')+'</svg>';
 }
 function strengthCard(r){const i=r.interpretation,s=i.strength,str=i.structure,key=s.label.split(' ')[0];return '<article class="strength-summary"><span class="eyebrow">'+context(r).dayPillar+' 일주 · '+s.label+(s.provisional?' / 시간 미상 추정':'')+'</span><h3>'+character(r)+'</h3><p>'+window.OngyeolContent.strengthGood[key]+'</p><p class="honest-line">'+window.OngyeolContent.strengthCaution[key]+'</p><div class="strength-parts"><span>득령<strong>'+round(s.season)+'</strong></span><span>득지<strong>'+round(s.rootScore)+'</strong></span><span>득세<strong>'+round(s.support)+'</strong></span></div><details><summary>참고 지표 '+round(s.score)+' / 100 · 어떻게 계산했나요?</summary><p>득령: 월지 '+r.pillars[1].zhi+'의 계절 오행 '+s.month+'와 일간의 '+s.seasonRelation+' 관계. 득지: 일지·시지 지장간의 같은 오행 통근 비중. 득세: 가중 분포 중 비겁·인성 비중. 비중은 40%·30%·30%이며 45 미만 신약, 55 초과 신강, 그 사이는 중간 경향입니다.</p><p>'+escape(i.version)+' · '+escape(str.limits)+'</p><p>월령 '+str.main+'('+str.ten+') → '+str.candidate+'. 투간: '+(str.visible.join(' · ')||'같은 천간 투간 없음')+'. 일반격 후보이며 성격과 운을 확정하지 않습니다.</p></details></article>';}
 function weightedCard(r){const i=r.interpretation,w=i.weighted,str=i.structure,q=window.OngyeolContent;return '<article class="weighted-card"><span class="eyebrow">지장간 · 월령을 함께 읽는 오행</span><h3>겉의 글자 수에서 한 걸음 더.</h3>'+radar(r)+'<div class="weighted-values">'+Object.entries(w.percent).map(([e,n])=>'<span>'+e+' <strong>'+round(n)+'%</strong></span>').join('')+'</div><p class="experience-note">레이더 바깥선은 비중 50%입니다. 50%를 넘는 값은 선 밖으로 확장하지 않으며 실제 수치는 위에 표시합니다.</p><div class="balance-tip"><strong>보완해볼 기운: '+(str.balanceCandidates.join('·')||'중간 경향 · 보완 후보 유보')+'</strong><p>억부 참고 규칙의 후보입니다. 가장 적은 오행이 곧 용신인 것은 아닙니다.</p>'+str.balanceCandidates.map(e=>'<p>'+q.elementTips[e][0]+': '+q.elementTips[e][1]+'</p>').join('')+'</div><details><summary>가중치와 적은 비중을 확인하기</summary><p>천간 각 1, 지지 지장간 합계는 연지 1·월지 2.4·일지 1.4·시지 1.2. 지장간이 1·2·3개이면 각각 1 / 0.7·0.3 / 0.6·0.3·0.1을 적용합니다. 지지 대표 오행을 추가로 중복 합산하지 않습니다.</p><p>가중 비중 10% 미만: '+(w.low.map(e=>e+' '+round(w.percent[e])+'%').join(' · ')||'없음')+'. 이는 능력이나 건강의 결핍 판정이 아닙니다.</p></details></article>';}
 function describeRelations(list){return list.length?list.map(f=>'<li><strong>'+escape(f.kind)+'</strong> '+escape(f.label)+(f.missing&&f.missing.length?' · 부족 '+f.missing.join('·'):'')+'</li>').join(''):'<li>현재 규칙에서 원국과 새로 연결된 관계 없음</li>';}
 function monthDetail(r,index){const m=r.interpretation.timeline.months[index];return '<span class="eyebrow">'+m.month+'월 · '+m.term+' 이후</span><h4>'+m.ganZhi+' 월운</h4><p>한국 시각 '+m.start+'부터<br>'+m.end+' 전까지</p><ul>'+describeRelations(m.relations)+'</ul><p class="experience-note">달력의 1일이 아니라 입절 순간부터 읽는 구간입니다. 날짜별 사건 예측이 아닙니다.</p>';}
 function timelines(r){const t=r.interpretation.timeline;return '<section class="fortune-timeline"><div class="personal-section-title"><div><span class="eyebrow">MY '+r.year+' TIMELINE</span><h3>올해, 어느 글자가 내 원국과 연결될까?</h3></div></div><div class="annual-highlights">'+t.years.map(y=>'<article><span>'+y.year+' · '+y.ganZhi+'</span><h4>'+ (y.relations.some(f=>f.kind==='충'&&f.members.some(p=>p.label==='일주'))?'일지와 세운이 충으로 연결돼요':'원국과 연결되는 글자를 살펴보세요')+'</h4><ul>'+describeRelations(y.relations)+'</ul></article>').join('')+'</div><div class="yun-change"><strong>'+ (t.active?'현재 대운 '+t.active.ganZhi+' · '+t.active.startDate+'부터':'현재는 표시한 대운 구간 밖입니다')+'</strong><p>'+ (t.next?'다음 교체 '+t.next.startDate+' · '+t.next.ganZhi+' 대운'+(t.next.startDate.startsWith(String(r.year))?' · 올해 교체':''):'다음 교체는 표시 범위 밖입니다')+'</p><p class="experience-note">교체일은 선택한 대운 환산에 따른 참고 날짜'+(r.interpretation.strength.provisional?' · 출생 시간 미상으로 추정':'')+'입니다.</p>'+ (t.active?'<details><summary>현재 대운과 원국의 합·충·형·파·해</summary><ul>'+describeRelations(t.active.relations)+'</ul></details>':'')+'</div><div class="month-switch" role="group" aria-label="월운 선택">'+t.months.map((m,i)=>'<button type="button" data-month="'+i+'" aria-pressed="'+(i===0)+'">'+m.month+'월<small>'+m.ganZhi+'</small></button>').join('')+'</div><div id="month-detail" class="month-detail" aria-live="polite">'+monthDetail(r,0)+'</div></section>';}
 function compare(a,b){
  const own=a.pillars.filter(p=>!p.unknown).map(p=>({...p,label:'나의 '+p.label})),other=b.pillars.filter(p=>!p.unknown).map(p=>({...p,label:'상대 '+p.label}));
  const all=window.OngyeolRelations.analyze([...own,...other]).found.filter(f=>f.members.some(v=>v.label.startsWith('나의'))&&f.members.some(v=>v.label.startsWith('상대')));
  const day=all.filter(f=>f.members.some(v=>v.label==='나의 일주')&&f.members.some(v=>v.label==='상대 일주'));
  return {relations:all,day,elementRelation:window.OngyeolInterpretation.relation(a.elements[a.day],b.elements[b.day]),unknown:a.interpretation.strength.provisional||b.interpretation.strength.provisional};
 }
 function comparisonHTML(a,b){const c=compare(a,b);return '<h4>나 '+context(a).dayPillar+' · 상대 '+context(b).dayPillar+'</h4><p>일간 오행을 내 기준에서 읽으면 '+c.elementRelation+' 관계입니다. 이것은 두 사람의 성격 검사나 궁합 점수가 아닙니다.</p><div><strong>두 일지의 관계</strong><ul>'+describeRelations(c.day)+'</ul></div><details><summary>두 원국 사이의 전체 관계 펼치기</summary><ul>'+describeRelations(c.relations)+'</ul></details><p>가까워질수록 말하지 않아도 알 것이라고 기대하기 쉽습니다. 서로 편한 연락 방식, 함께 결정할 일과 각자 결정할 일을 직접 맞춰보세요.</p><p class="experience-note">'+(c.unknown?'시간 미상인 기둥은 비교에서 제외했습니다. ':'')+'합이 좋음·충이 나쁨이라는 점수로 합산하지 않습니다. 상대 정보는 이 화면에서만 처리됩니다.</p>';}
 function render(r){return '<section class="insight-dashboard"><div class="personal-section-title"><div><span class="eyebrow">YOUR CHART, YOUR PATTERNS</span><h3>일주와 힘의 균형으로 읽는 나.</h3></div></div><div class="insight-grid">'+strengthCard(r)+weightedCard(r)+'</div><div class="feature-tags">'+r.interpretation.tags.map(t=>'<span title="'+escape(t.evidence)+'">'+escape(t.id.replace(/_/g,' '))+'</span>').join('')+'</div></section>'+timelines(r)+'<section class="category-insights"><div class="personal-section-title"><div><span class="eyebrow">LIFE, IN FOUR SCENES</span><h3>좋게 쓰는 힘과 놓치기 쉬운 장면.</h3></div></div><div class="category-switch" role="group" aria-label="생활 해석 주제">'+window.OngyeolContent.categories.map(([key,label],i)=>'<button type="button" data-category="'+key+'" aria-pressed="'+(i===0)+'">'+label+'</button>').join('')+'</div><div id="category-content" aria-live="polite">'+category(r)+'</div></section><section class="special-overview"><h3>추가로 눈에 띄는 신살</h3><div>'+r.interpretation.special.map(s=>'<article><strong>'+s.name+'</strong><span>'+s.status+'</span><p>'+escape(s.hits.join(' · ')||'확인된 위치 없음')+'</p><small>'+escape(s.basis)+'</small></article>').join('')+'</div><p class="experience-note">귀문·백호를 포함한 표기는 공개된 고정 규칙의 일치 여부이며 정신 상태·사고·질병을 판정하지 않습니다.</p></section><section class="couple-section"><span class="eyebrow">TWO CHARTS, ONE CONVERSATION</span><h3>둘의 글자는 어떻게 만날까?</h3><form id="compare-form"><div class="fields"><label>상대 양력 생일<input type="date" id="partner-date" min="1948-01-01" required></label><label>상대 출생 시간<input type="time" id="partner-time" value="12:00" required></label><label>상대 대운 계산 성별<select id="partner-gender"><option value="0">여성</option><option value="1">남성</option></select></label><label>상대 출생지 경도<input id="partner-longitude" type="number" value="126.978" min="124" max="132" step="0.001" required></label></div><label class="equation-option"><input id="partner-unknown" type="checkbox"> 상대 출생 시간 미상</label><p class="experience-note">내 분석과 같은 보정·일주 변경·대운 계산 설정을 적용합니다. 전환 시각이 겹치는 기록은 확인 후 입력해주세요.</p><button type="submit" class="outline">두 원국 비교하기 →</button><p id="compare-error" role="alert" class="error"></p></form><div id="compare-result" aria-live="polite"></div></section><section class="share-result"><span class="eyebrow">MY ONE-LINE CARD</span><h3>내 한 줄, 카드로 간직하기.</h3><div class="share-preview"><span>온결 · '+context(r).dayPillar+' 일주</span><strong>'+character(r)+'</strong><p>'+r.interpretation.strength.label+' · '+r.interpretation.tags.slice(1,4).map(v=>v.id.replace(/_/g,' ')).join(' · ')+'</p></div><button type="button" data-download-card="true" class="outline">결과 카드 이미지 저장 →</button><p id="share-status" aria-live="polite" class="experience-note">생년월일·출생 시간은 카드에 넣지 않습니다.</p></section>';}
 async function download(r){const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1080;const ctx=canvas.getContext('2d');ctx.fillStyle='#193c34';ctx.fillRect(0,0,1080,1080);ctx.strokeStyle='#ac9360';ctx.strokeRect(55,55,970,970);ctx.fillStyle='#d0b77b';ctx.font='28px sans-serif';ctx.fillText('온결 · '+context(r).dayPillar+' 일주',100,150);ctx.fillStyle='#faf7ed';ctx.font='48px serif';const sentence=character(r);let line='',y=320;for(const ch of sentence){if(ctx.measureText(line+ch).width>850){ctx.fillText(line,100,y);y+=80;line=ch;}else line+=ch;}ctx.fillText(line,100,y);ctx.font='28px sans-serif';ctx.fillStyle='#d5deca';ctx.fillText(r.interpretation.strength.label,100,760);ctx.font='22px sans-serif';ctx.fillText(r.interpretation.tags.slice(1,4).map(v=>v.id.replace(/_/g,' ')).join(' · '),100,825);ctx.font='19px sans-serif';ctx.fillText('전통 상징으로 읽는 오락·참고용 리포트',100,970);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('카드 이미지를 만들지 못했습니다.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='온결_'+context(r).dayPillar+'_결과카드.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
 window.OngyeolInsights={render,category,select,character,monthDetail,compare,comparisonHTML,download};
})();
